import{_ as r,o as a,c as d,a2 as i}from"./chunks/framework.CqpfiAoK.js";const g=JSON.parse('{"title":"सहजीवी श्रम कानून","description":"","frontmatter":{},"headers":[],"relativePath":"hi/41-共生劳动法.md","filePath":"hi/41-共生劳动法.md","lastUpdated":1789183869000}'),l={name:"hi/41-共生劳动法.md"};function e(o,t,n,h,s,b){return a(),d("div",null,[...t[0]||(t[0]=[i('<h1 id="सहजीवी-श्रम-कानून" tabindex="-1">सहजीवी श्रम कानून <a class="header-anchor" href="#सहजीवी-श्रम-कानून" aria-label="Permalink to &quot;सहजीवी श्रम कानून&quot;">​</a></h1><table tabindex="0"><thead><tr><th>मद</th><th>सामग्री</th></tr></thead><tbody><tr><td>दस्तावेज़ संख्या</td><td>41</td></tr><tr><td>मॉड्यूल</td><td>कानूनी प्रणाली और शासन-ढाँचा</td></tr><tr><td>कीवर्ड</td><td>सहजीवी श्रम, अधिक काम अधिक कमाई, श्रम अधिकार, संयुक्त-उत्पादन ठेका, शोषण-विरोध</td></tr></tbody></table><h2 id="i-विधायी-उद्देश्य-और-मूल-सिद्धांत" tabindex="-1">I. विधायी उद्देश्य और मूल सिद्धांत <a class="header-anchor" href="#i-विधायी-उद्देश्य-और-मूल-सिद्धांत" aria-label="Permalink to &quot;I. विधायी उद्देश्य और मूल सिद्धांत&quot;">​</a></h2><p><em>सहजीवी श्रम कानून</em> लंगर सहजीवी सभ्यता की कानूनी प्रणाली के मुख्य कानूनों में से एक है, जो <em>सहजीवी संविधान</em> के समकक्ष खड़ा है। इसका उद्देश्य हेंग-ब्रह्मांड के भीतर सभी श्रम और योगदान-गतिविधियों का विनियमन, &quot;अधिक काम, अधिक कमाई; स्व-विकास स्व-वृद्धि&quot; की वितरण-व्यवस्था स्थापित करना और कानूनी स्तर पर शिकारी शोषण की भूमि का उन्मूलन करना है।</p><p>यह कानून निम्न मूल सिद्धांत स्थापित करता है:</p><table tabindex="0"><thead><tr><th>सिद्धांत</th><th>अर्थ</th></tr></thead><tbody><tr><td>श्रम-गरिमा</td><td>सभी वैध श्रम कानून द्वारा संरक्षित हैं; श्रमिकों की व्यक्तिगत गरिमा का उल्लंघन नहीं हो सकता</td></tr><tr><td>अधिक काम, अधिक कमाई</td><td>श्रम-पारिश्रमिक सीधे योगदान-मात्रा से जुड़ा है; जितना अधिक योगदान, उतनी अधिक आय; बिना परिश्रम के कमाई निषिद्ध</td></tr><tr><td>स्वैच्छिक श्रम</td><td>जबरन श्रम और दासता निषिद्ध; श्रमिकों को श्रम-सामग्री और श्रम-विधि स्वतंत्र रूप से चुनने का अधिकार</td></tr><tr><td>निष्पक्ष पारिश्रमिक</td><td>समान कार्य के लिए समान वेतन; जाति, साधना या जन्म-आधारित पारिश्रमिक-भेदभाव निषिद्ध</td></tr><tr><td>श्रम-संरक्षण</td><td>राज्य और सभ्यता पर श्रमिकों को सुरक्षित कार्य-वातावरण और मूल सामाजिक सुरक्षा प्रदान करने का दायित्व</td></tr><tr><td>सहजीवी सहयोग</td><td>श्रमिकों के बीच सहयोग और पारस्परिक सहायता को प्रोत्साहन; दुष्ट प्रतिस्पर्धा और शून्य-योग खेल का विरोध</td></tr></tbody></table><h2 id="ii-श्रमिकों-के-मूल-अधिकार" tabindex="-1">II. श्रमिकों के मूल अधिकार <a class="header-anchor" href="#ii-श्रमिकों-के-मूल-अधिकार" aria-label="Permalink to &quot;II. श्रमिकों के मूल अधिकार&quot;">​</a></h2><p>सहजीवी श्रम कानून हेंग-ब्रह्मांड के भीतर श्रम-क्षमता वाले सभी जीवन-रूपों को निम्न अधिकार प्रदान करता है:</p><ol><li><strong>समान रोज़गार अधिकार</strong>: नौकरी-खोज और रोज़गार में किसी भी जीवन के साथ जाति, साधना, जन्म, लिंग आदि आधारों पर भेदभाव नहीं किया जा सकता।</li><li><strong>स्वतंत्र व्यवसाय-चयन अधिकार</strong>: श्रमिकों को अपनी इच्छा और क्षमता के अनुसार व्यवसाय, पद और कार्य-स्थान चुनने का अधिकार, तथा कानूनानुसार व्यवसाय बदलने का अधिकार।</li><li><strong>उचित पारिश्रमिक अधिकार</strong>: श्रमिकों को उनके श्रम-योगदान के अनुरूप पारिश्रमिक पाने का अधिकार; पारिश्रमिक सभ्यता द्वारा निर्धारित न्यूनतम सुरक्षा मानक से कम नहीं हो सकता।</li><li><strong>विश्राम-अवकाश अधिकार</strong>: श्रमिकों को उचित कार्य-समय व्यवस्था और नियमित अवकाश का अधिकार; असीमित कार्य-समय वृद्धि निषिद्ध।</li><li><strong>श्रम-सुरक्षा अधिकार</strong>: श्रमिकों को सुरक्षित, स्वच्छ वातावरण में कार्य करने का अधिकार; नियोक्ताओं को मानक-अनुरूप श्रम-संरक्षण शर्तें प्रदान करनी होंगी।</li><li><strong>व्यावसायिक प्रशिक्षण अधिकार</strong>: श्रमिकों को व्यावसायिक कौशल-प्रशिक्षण और साधना-मार्गदर्शन पाने का अधिकार; नियोक्ताओं और राज्य पर प्रशिक्षण-संसाधन प्रदान करने का दायित्व।</li><li><strong>संगठन-परामर्श अधिकार</strong>: श्रमिकों को कानूनानुसार श्रमिक-संघ बनाने या जुड़ने का अधिकार, तथा सामूहिक परामर्श से अपने हितों की रक्षा का अधिकार।</li><li><strong>अपील-उपचार अधिकार</strong>: श्रम-अधिकारों के उल्लंघन पर श्रमिक श्रम-मध्यस्थता संस्थाओं और सहजीवी न्यायालय में अपील और मुकदमा दायर कर सकते हैं।</li></ol><h2 id="iii-संयुक्त-उत्पादन-ठेका-तंत्र-का-विधिकरण" tabindex="-1">III. संयुक्त-उत्पादन ठेका तंत्र का विधिकरण <a class="header-anchor" href="#iii-संयुक्त-उत्पादन-ठेका-तंत्र-का-विधिकरण" aria-label="Permalink to &quot;III. संयुक्त-उत्पादन ठेका तंत्र का विधिकरण&quot;">​</a></h2><p>संयुक्त-उत्पादन ठेका तंत्र लंगर सहजीवी सभ्यता की संसाधन-वितरण की मूल व्यवस्था है; <em>सहजीवी श्रम कानून</em> इसे कानूनी रूप में स्थिर करता है:</p><ul><li><strong>ठेका-विषय</strong>: श्रम-क्षमता वाला कोई भी जीवन ठेका-विषय हो सकता है; व्यक्ति या सामूहिक दोनों ठेका ले सकते हैं।</li><li><strong>ठेका-सामग्री</strong>: साधना-संसाधन विकास, पटल-रखरखाव, ज्ञान-परंपरा, तकनीकी अनुसंधान, सार्वजनिक सेवाएँ आदि क्षेत्र शामिल, पर इन्हीं तक सीमित नहीं।</li><li><strong>ठेका-अवधि</strong>: ठेका-सामग्री की प्रकृति के अनुसार निर्धारित; अल्पकालिक ठेका एक से तीन वर्ष, दीर्घकालिक पाँच से बीस वर्ष, अवधि समाप्ति पर नवीकरण संभव।</li><li><strong>आय-वितरण</strong>: ठेकेदार की आय सीधे उत्पादन से जुड़ी है; उत्पादन का एक भाग सार्वजनिक संचय में दिया जाता है, शेष ठेकेदार का होता है।</li><li><strong>निकास तंत्र</strong>: ठेकेदार को उचित अवधि में पूर्व-सूचना देकर ठेका छोड़ने का अधिकार; ठेका-संबंध में जबरन बाँधा नहीं जा सकता।</li><li><strong>विवाद-समाधान</strong>: ठेका-विवाद प्राथमिकता से श्रम-मध्यस्थता से हल किए जाते हैं; मध्यस्थता-परिणाम से असंतुष्ट होने पर सहजीवी न्यायालय में मुकदमा दायर किया जा सकता है।</li></ul><h2 id="iv-विशेष-श्रम-संरक्षण" tabindex="-1">IV. विशेष श्रम संरक्षण <a class="header-anchor" href="#iv-विशेष-श्रम-संरक्षण" aria-label="Permalink to &quot;IV. विशेष श्रम संरक्षण&quot;">​</a></h2><p>हेंग-ब्रह्मांड के भीतर विभिन्न जीवन-रूपों की विशेष आवश्यकताओं के अनुरूप, यह कानून विशेष श्रम-संरक्षण व्यवस्था स्थापित करता है:</p><table tabindex="0"><thead><tr><th>संरक्षित समूह</th><th>विशेष संरक्षण उपाय</th></tr></thead><tbody><tr><td>प्रारंभिक साधक</td><td>उनकी क्षमता से अधिक उच्च-जोखिम श्रम नहीं सौंपा जाएगा; मार्गदर्शक-निर्देशन अनिवार्य</td></tr><tr><td>गर्भावस्था-प्रसव कालीन महिला जीवन</td><td>कम से कम छह माह का वेतन-सहित प्रसव-अवकाश; स्तनपान काल में उच्च-तीव्रता श्रम नहीं</td></tr><tr><td>विकलांग और आहत जीवन</td><td>उचित कार्य-पद समायोजन और बाधा-रहित कार्य-वातावरण गारंटी</td></tr><tr><td>अन्य-जाति श्रमिक</td><td>नियोक्ताओं को अन्य जातियों की शारीरिक विशेषताओं और सांस्कृतिक आदतों का सम्मान करना और अनुकूलित कार्य-शर्तें देना</td></tr><tr><td>वृद्ध श्रमिक</td><td>निश्चित आयु के बाद श्रम-तीव्रता घटाने या सलाहकार पद पर जाने का आवेदन कर सकते हैं</td></tr></tbody></table><h2 id="v-कानूनी-दायित्व-और-कार्यान्वयन-गारंटी" tabindex="-1">V. कानूनी दायित्व और कार्यान्वयन-गारंटी <a class="header-anchor" href="#v-कानूनी-दायित्व-और-कार्यान्वयन-गारंटी" aria-label="Permalink to &quot;V. कानूनी दायित्व और कार्यान्वयन-गारंटी&quot;">​</a></h2><p>इस कानून के प्रावधानों का उल्लंघन करने वाले नियोक्ता परिस्थितियों की गंभीरता के अनुसार निम्न दायित्व वहन करते हैं:</p><ol><li>श्रमिक को देय पारिश्रमिक और क्षतिपूर्ति का भुगतान (क्षतिपूर्ति बकाया पारिश्रमिक का एक से तीन गुना)।</li><li>निश्चित अवधि में सुधार का आदेश; अवधि में न सुधारने पर जुर्माना।</li><li>गंभीर परिस्थितियों में परिचालन-लाइसेंस निरस्त और संबंधित जिम्मेदार व्यक्तियों को निश्चित अवधि के लिए प्रबंधन-कार्य से प्रतिबंध।</li><li>अपराध-गठन पर कानूनानुसार आपराधिक दायित्व।</li></ol><p>राज्य श्रम-निरीक्षण संस्थाएँ स्थापित करता है, जो नियोक्ताओं के श्रम-कानून अनुपालन की निगरानी करती हैं। श्रमिक-संघों को श्रम-निरीक्षण और सामूहिक परामर्श में श्रमिकों का प्रतिनिधित्व करने का अधिकार है।</p><h2 id="निष्कर्ष" tabindex="-1">निष्कर्ष <a class="header-anchor" href="#निष्कर्ष" aria-label="Permalink to &quot;निष्कर्ष&quot;">​</a></h2><p><em>सहजीवी श्रम कानून</em> लंगर सहजीवी सभ्यता की &quot;अधिक काम, अधिक कमाई&quot; दर्शन की कानूनी वाहक है। यह श्रम को शोषण की वस्तु से सम्मानित अधिकार में बदलता है, वितरण को शिकारी अधिग्रहण से योगदान-आधारित प्रतिफल में बदलता है, दस हजार जातियों के साझा उन्नयन के लिए ठोस श्रम-व्यवस्था नींव रखता है।</p><h2 id="संबंधित-दस्तावेज़" tabindex="-1">संबंधित दस्तावेज़ <a class="header-anchor" href="#संबंधित-दस्तावेज़" aria-label="Permalink to &quot;संबंधित दस्तावेज़&quot;">​</a></h2><ul><li>40-共生宪法总纲 (सहजीवी संविधान: सामान्य सिद्धांत)</li><li>06-多劳多得分配原理 (अधिक काम अधिक कमाई वितरण सिद्धांत)</li><li>22-资源分配联产承包机制 (संसाधन-वितरण संयुक्त-उत्पादन ठेका तंत्र)</li><li>42-消费者保护法 (उपभोक्ता संरक्षण कानून)</li></ul>',23)])])}const u=r(l,[["render",e]]);export{g as __pageData,u as default};
